#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NO_INPUT");
        return 0;
    }
    char *endptr = NULL;
    long n = strtol(argv[1], &endptr, 10);
    if (endptr == argv[1] || *endptr != '\0') {
        puts("BAD_INPUT");
        return 0;
    }
    if (n < 0) {
        puts("BAD_INPUT");
        return 0;
    }
    if (n == 0) {
        puts("EMPTY");
        return 0;
    }
    if (n > 60) {
        puts("OUT_OF_RANGE");
        return 0;
    }
    long long row[61] = {0};
    row[0] = 1;
    for (int r = 0; r < n; ++r) {
        if (r > 0) {
            row[r] = 1;
            for (int i = r - 1; i > 0; --i) {
                row[i] = row[i] + row[i - 1];
            }
        }
        for (int c = 0; c <= r; ++c) {
            printf("%lld", row[c]);
            if (c < r) putchar(' ');
        }
        putchar('\n');
    }
    return 0;
}
